import * as architecture from './architecture.js';import * as transport from './transport.js';
import {WATER} from './water.js';import {SPRINGS} from './infrastructure.js';import {LOCAL_LIFT} from './local-lift-config.js';
const phases=['A','B','C'],round=x=>Math.round(x*10000)/10000;
export const DIAGNOSTIC_COLORS={moving:'#318b76',waiting:'#b18b46',fixed:'#658eaf'};
export const fixedEquipment=()=>[
 {id:'EV',name:'主EV・固定昇降路',kind:'fixed',x:-6.8,y:-13,z:1.8,w:4.4,d:4.4,h:32},
 {id:'HOUSING-EV',name:'居住区EV・固定昇降路',kind:'fixed',...LOCAL_LIFT.shaft,y:-13,h:19.2},
 ...SPRINGS.map(p=>({...p,kind:'fixed',name:'固定泉 '+p.id,h:6})),...WATER.map(p=>({...p,kind:'fixed'}))
];
// Model injection lets the same measurement code inspect the exact frozen source, not reconstructed estimates.
export function auditFacility(e=architecture.DEFAULT_EXPERIMENT,A=architecture,T=transport){
 const doors=Object.fromEntries(Object.keys(A.defaultDoors()).map(k=>[k,true])),poses=Object.fromEntries(phases.map(p=>[p,A.placements(p,e)])),plans=phases.map(p=>T.planTransfer(p,A.NEXT[p],e)),links=Object.fromEntries(phases.map(p=>[p,A.connections(p,e,doors)]));
 const records=A.BODIES.map(b=>{const transitions=Object.fromEntries(plans.map(p=>{let distance=0,horizontal=0,vertical=0,rotation=0;const legs=[];for(const [stage,s]of p.stages.entries())for(const m of s.motions.filter(m=>m.id===b.id)){const dx=m.to.x-m.from.x,dy=m.to.y-m.from.y,dz=m.to.z-m.from.z,angle=(m.to.angle??0)-(m.from.angle??0);distance+=Math.hypot(dx,dy,dz);horizontal+=Math.hypot(dx,dz);vertical+=Math.abs(dy);rotation+=Math.abs(angle);legs.push({stage,from:m.from,to:m.to,duration:s.duration});}const a=poses[p.from][b.id],c=poses[p.to][b.id];return[p.from,{to:p.to,distance:round(distance),horizontal:round(horizontal),vertical:round(vertical),rotation:round(rotation),dockDisplacement:round(Math.hypot(c.x-a.x,c.y-a.y,c.z-a.z)),legs}];})),moved=Object.values(transitions).some(t=>t.distance>.001||t.rotation>.001),dockMoved=phases.some(p=>transitions[p].dockDisplacement>.001||transitions[p].rotation>.001);
  return{id:b.id,name:b.name,cells:b.cells.length,generation:b.mobility?.generation??b.generation??null,kind:'transportable',classification:moved?'moving':'waiting',poses:Object.fromEntries(phases.map(p=>[p,{...poses[p][b.id],angle:poses[p][b.id].angle??0}])),transitions,moved,dockMoved,purpose:b.mobility?.purpose??(moved?'旧搬送リストに登録された目標への搬送':'旧ABC目標が同一で搬送ジョブがない。固定設備の指定はない'),connections:Object.fromEntries(phases.map(p=>[p,links[p].filter(c=>c.status==='pass'&&(c.bodyA===b.id||c.bodyB===b.id)).map(c=>({body:c.bodyA===b.id?c.bodyB:c.bodyA,port:c.bodyA===b.id?c.portA:c.portB,otherPort:c.bodyA===b.id?c.portB:c.portA,width:round(c.width)}))]))};
 });
 const fixed=fixedEquipment().map(q=>({...q,cells:q.tunnel?null:q.id.startsWith('W')?1:null,classification:'fixed',moved:false,purpose:'明示的な固定設備。搬送目標に含めない',poses:Object.fromEntries(phases.map(p=>[p,{x:q.x,y:q.y,z:q.z,angle:0}])),transitions:Object.fromEntries(phases.map(p=>[p,{to:A.NEXT[p],distance:0,horizontal:0,vertical:0,rotation:0,dockDisplacement:0,legs:[]}])),connections:Object.fromEntries(phases.map(p=>[p,links[p].filter(c=>c.status==='pass'&&[c.bodyA,c.bodyB].includes(q.id)).map(c=>({body:c.bodyA===q.id?c.bodyB:c.bodyA,width:round(c.width)}))]))}));
 const phaseSummary=Object.fromEntries(phases.map(p=>{const walk=A.reachable(p,e,doors),service=A.serviceReachable(p,e,doors);const regions=A.BODIES.flatMap(b=>A.localNavigation(b,doors).components.map(c=>({node:b.id+'/'+c.id,body:b.id,level:A.LEVELS.indexOf(poses[p][b.id].y),cells:c.cells,reachable:walk.has(b.id+'/'+c.id),serviceReachable:service.has(b.id+'/'+c.id),reason:b.id==='R3'&&c.id===A.localNavigation(b,doors).componentAt(1.55,6.25)?'身体では入らず固定3D視点で訪問する簡易個室':b.remote?'帰還便を利用する遠隔区域':b.id==='C0'||b.id==='Q1'?'周期により保管される予備廊下':'建築の仕切りと周期の接続で区分された通路成分'})));return[p,{regions,connections:links[p].filter(c=>c.status==='pass').length,walkRegions:[...walk].sort(),serviceRegions:[...service].sort(),unreachable:records.filter(b=>![...walk].some(n=>n.startsWith(b.id+'/'))).map(b=>({id:b.id,service:[...service].some(n=>n.startsWith(b.id+'/')),reason:b.id==='S1'||b.id.startsWith('D')?'遠隔区域はS1の帰還便による接続':b.id==='C0'||b.id==='Q1'?'保管中の予備廊下':b.id==='W1'?'Bで点検廊下が挿入される目的地':'次周期に再接続する枝。残留時は既存の退避・再接続機構で扱う'})),water:WATER.map(q=>({id:q.id,reachable:walk.has(q.id)}))}];}));
 return{experiment:e,reference:'通常扉全開・完了配置の通行接続。距離は全実搬送区間の和、dockDisplacementは目標間の直線距離',records,fixed,phases:phaseSummary,summary:{bodies:records.length,cells:records.reduce((n,r)=>n+r.cells,0),transportable:records.length,fixedEquipment:fixed.length,moved:records.filter(r=>r.moved).length,waiting:records.filter(r=>!r.moved).length,duration:round(plans.reduce((n,p)=>n+p.duration,0)),transitions:plans.map(p=>({from:p.from,to:p.to,duration:p.duration,ok:T.validatePlan(p).ok}))}};
}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function diagnosticDetail(audit,id,phase){const r=[...audit.records,...audit.fixed].find(r=>r.id===id);if(!r)return'';const state=r.kind==='fixed'?'固定設備':r.moved?'実搬送する可動体':'現在の計画で待機する可動体';return`<h4>${escape(r.id)} · ${escape(r.name)}</h4><p>${state} / ${r.cells??'—'}チャンク</p><p>${escape(r.purpose)}</p><table><thead><tr><th>周期</th><th>位置 X / Y / Z (m)</th><th>向き</th></tr></thead><tbody>${phases.map(p=>{const q=r.poses[p];return`<tr class="${p===phase?'active-phase':''}"><td>${p}</td><td>${q.x} / ${q.y} / ${q.z}</td><td>${q.angle}°</td></tr>`;}).join('')}</tbody></table><p>実経路 / 目標変位 / 回転 / 上下移動</p>${phases.map(p=>{const t=r.transitions[p];return`<p>${p}→${t.to}：${t.distance.toFixed(1)}m / ${t.dockDisplacement.toFixed(1)}m / ${t.rotation}° / ${t.vertical.toFixed(1)}m<br><small>接続：${r.connections[p].map(c=>escape(c.body)+' '+c.width+'m').join('、')||'なし'}</small></p>`;}).join('')}`;}
export function diagnosticTable(audit,phase){return`<table><thead><tr><th>ID・区分</th><th>チャンク</th>${phases.map(p=>`<th>${p}→${architecture.NEXT[p]} m</th>`).join('')}</tr></thead><tbody>${[...audit.records,...audit.fixed].map(r=>`<tr data-diagnostic-id="${r.id}" style="--diagnostic-color:${DIAGNOSTIC_COLORS[r.classification]}"><td><button data-diagnostic-id="${r.id}">${r.id} · ${r.classification==='fixed'?'固定':r.moved?'搬送':'待機'}</button></td><td>${r.cells??'—'}</td>${phases.map(p=>`<td class="${p===phase&&(r.transitions[p].distance>0||r.transitions[p].rotation>0)?'active-phase':''}">${r.transitions[p].distance.toFixed(1)}${r.transitions[p].rotation?' ↻':''}</td>`).join('')}</tr>`).join('')}</tbody></table>`;}
